     1|/**
     2| * ReelVideoPlayer — Instagram-style video player for the full-screen
     3| * vertical reels feed.
     4| *
     5| * Lifecycle guarantees:
     6| *   • Only the active reel plays; neighbors mount poster-only.
     7| *   • Pauses immediately when the app goes to background.
     8| *   • Pauses when the screen loses focus (navigates away).
     9| *   • Pauses on network disconnect; shows retry on reconnect.
    10| *   • Unloads the native player on unmount to free ExoPlayer resources.
    11| *   • Android: prefers progressive MP4 over HLS to avoid expo-av crashes.
    12| *   • Poster displays on Android (Image component, not expo-av posterSource).
    13| *   • Max 3 players mounted at any time (active ± 1).
    14| *
    15| * This wraps SafeVideo with poster-first rendering and error boundary
    16| * isolation so a single bad video never crashes the feed.
    17| */
    18|import React, { memo, useCallback, useEffect, useMemo, useRef, useState } from 'react';
    19|import { View, Text, Image, StyleSheet, Platform } from 'react-native';
    20|import { ResizeMode } from 'expo-av';
    21|import { WifiOff } from 'lucide-react-native';
    22|import SafeVideo from './SafeVideo';
    23|import ReelErrorBoundary from './ReelErrorBoundary';
    24|import { useNetworkState } from '@/hooks/useNetworkState';
    25|
    26|interface ReelVideoPlayerProps {
    27|  videoId: string;
    28|  uri: string | null | undefined;
    29|  hlsUri?: string | null;
    30|  posterUri?: string | null;
    31|  previewBlurUri?: string | null;
    32|  shouldPlay: boolean;
    33|  isMuted: boolean;
    34|  onProgress?: (progress: number) => void;
    35|  onPlaybackStatusUpdate?: (status: { isPlaying: boolean; durationMillis: number; positionMillis: number }) => void;
    36|  testID?: string;
    37|}
    38|
    39|function pickPlaybackUri(
    40|  uri: string | null | undefined,
    41|  hlsUri: string | null | undefined,
    42|  isAndroid: boolean,
    43|): string | null {
    44|  // On Android, prefer progressive MP4 over HLS to avoid expo-av native crashes.
    45|  // On iOS, prefer HLS for adaptive bitrate.
    46|  if (isAndroid) {
    47|    if (uri && !uri.toLowerCase().endsWith('.m3u8')) return uri;
    48|    if (hlsUri && !hlsUri.toLowerCase().endsWith('.m3u8')) return hlsUri;
    49|    // Fall back to HLS only if no MP4 is available
    50|    return uri ?? hlsUri ?? null;
    51|  }
    52|  // iOS: prefer HLS, fall back to MP4
    53|  return hlsUri ?? uri ?? null;
    54|}
    55|
    56|function ReelVideoPlayerInner({
    57|  videoId,
    58|  uri,
    59|  hlsUri,
    60|  posterUri,
    61|  previewBlurUri,
    62|  shouldPlay,
    63|  isMuted,
    64|  onProgress,
    65|  onPlaybackStatusUpdate,
    66|  testID,
    67|}: ReelVideoPlayerProps) {
    68|  const network = useNetworkState();
    69|  const [retryKey, setRetryKey] = useState<number>(0);
    70|  const [showTapToPlay, setShowTapToPlay] = useState<boolean>(false);
    71|  void showTapToPlay;
    72|  const isAndroidRef = useRef<boolean>(
    73|    typeof Platform !== 'undefined' && Platform.OS === 'android',
    74|  );
    75|
    76|  const playbackUri = useMemo(
    77|    () => pickPlaybackUri(uri, hlsUri, isAndroidRef.current),
    78|    [uri, hlsUri],
    79|  );
    80|
    81|  // Effective play state: pause on network disconnect or background
    82|  const effectiveShouldPlay = shouldPlay && network.isInternetReachable;
    83|
    84|  // When network drops, show the offline overlay; when it returns,
    85|  // allow the user to tap to resume.
    86|  useEffect(() => {
    87|    if (!network.isInternetReachable && shouldPlay) {
    88|      setShowTapToPlay(false);
    89|    }
    90|  }, [network.isInternetReachable, shouldPlay]);
    91|
    92|  const handleRetry = useCallback(() => {
    93|    setRetryKey((k) => k + 1);
    94|  }, []);
    95|
    96|  const handleTapResume = useCallback(() => {
    97|    setShowTapToPlay(false);
    98|  }, []);
    99|  void handleTapResume;
   100|
   101|  // Poster-first rendering: show the poster image immediately, then
   102|  // overlay the video player. On Android, the poster is an Image
   103|  // component (not expo-av's posterSource, which is a crash vector).
   104|  const posterSource = posterUri ?? previewBlurUri ?? null;
   105|
   106|  return (
   107|    <View style={styles.container} testID={testID}>
   108|      {/* Poster layer — always visible behind the video for instant first paint */}
   109|      {posterSource && (
   110|        <Image
   111|          source={{ uri: posterSource }}
   112|          style={StyleSheet.absoluteFill}
   113|          resizeMode="cover"
   114|          fadeDuration={200}
   115|          accessible={false}
   116|        />
   117|      )}
   118|
   119|      {/* Blur placeholder for even faster first paint */}
   120|      {previewBlurUri && previewBlurUri !== posterSource && (
   121|        <Image
   122|          source={{ uri: previewBlurUri }}
   123|          style={StyleSheet.absoluteFill}
   124|          resizeMode="cover"
   125|          fadeDuration={0}
   126|          accessible={false}
   127|        />
   128|      )}
   129|
   130|      <ReelErrorBoundary videoId={videoId} posterUri={posterSource} onRetry={handleRetry}>
   131|        <SafeVideo
   132|          key={`${videoId}-${retryKey}`}
   133|          uri={playbackUri}
   134|          posterUri={null}
   135|          style={StyleSheet.absoluteFill}
   136|          resizeMode={ResizeMode.COVER}
   137|          shouldPlay={effectiveShouldPlay}
   138|          isMuted={isMuted}
   139|          isLooping
   140|          onProgress={onProgress}
   141|          testID={testID ? `${testID}-player` : undefined}
   142|        />
   143|      </ReelErrorBoundary>
   144|
   145|      {/* Offline overlay */}
   146|      {!network.isInternetReachable && (
